import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`stakeholder-update`,heroTitle:`Write your stakeholder update in minutes`,heroSubtitle:`Perplexity Computer turns raw sprint outcomes, metrics, and blockers into a polished stakeholder update with context, decisions needed, and next steps.`,inputUrlCta:`Write this update`,inputUrlPlaceholder:`e.g. docs.google.com/document/... or your weekly notes`,inputUrlPrefill:`Go to {url} and draft a polished stakeholder update. (1) Review the recent sprint outcomes, key metrics, blockers, and decisions needed. (2) Summarize progress against the main goals or OKRs. (3) Explain notable metric movement with concise context. (4) Call out blockers, decisions, and risks that leadership should know about. (5) End with the priorities for next week. (6) Deliver the update in an executive-friendly format that is ready to send with minimal editing.`,heroOverlaySteps:[`Reviewing wins, misses, metrics, and open blockers from the latest work`,`Summarizing progress against goals and explaining what changed this week`,`Framing the risks, decisions, and next steps leadership should focus on`,`Stakeholder update with executive summary and priorities ready to send`],generatingSteps:[`Reading {url} to understand outcomes, metrics, blockers, and what needs to be communicated`,`Designing an agent to summarize progress and turn raw notes into leadership-ready messaging`,`Configuring the update with executive summary, metric context, asks, and next steps`,`Packaging the output into a sendable stakeholder update for leadership or cross-functional partners`],featureSectionTitle:`From scattered notes to leadership-ready update`,featureCardTitles:[`Connects to your reporting workflow`,`Outputs you can send as-is`],featureCardDescriptions:[`Computer breaks the work into progress synthesis, metric interpretation, risk framing, and message polishing so the update is concise without losing substance.`,`Docs, Notion, Slack notes, dashboards, and planning docs can stay connected so your weekly reporting pulls from the same source material.`,`Executive summary. Progress against goals. Metric context. Decisions needed. Next priorities. Computer delivers the update leadership expects to see.`],capabilitySectionTitle:`Your product comms writer, on demand`,capabilitySectionSubtitle:`Share the weekly context and come back to a crisp update with the right level of detail.`,capabilityCards:[{title:`Outcome Synthesis`,description:`Computer can distill the week into the wins, misses, and important changes that stakeholders actually need to know.`},{title:`Metric Storytelling`,description:`Computer can explain movement in the numbers with enough context to make the update useful without turning it into a dashboard dump.`},{title:`Decision Framing`,description:`Computer can elevate blockers, asks, and tradeoffs so leadership can respond quickly to what matters most.`},{title:`Connect Your Tools`,description:`Computer can pull from docs, dashboards, and notes so the update stays connected to the sources your team already maintains.`},{title:`Executive Polish`,description:`Computer can tighten the writing into a concise, leadership-friendly format that is easy to scan and hard to misread.`},{title:`Weekly Iteration`,description:`Computer can revisit the format each week and keep the update style consistent as priorities and audiences shift.`}]});export{t as default};
